const posOf = (k: string): PartOfSpeech =>
  k === 'der' || k === 'die' || k === 'das' || k === 'n' ? 'noun' : k === 'v' ? 'verb' : k === 'a' ? 'adj' : k === 'p' ? 'phrase' : 'other'

const counters: Record<number, number> = {}
const base = rows.map(([unit, kind, de, plural, ru, ky, example, exampleRu, exampleKy, pluralOnly]) => {
  counters[unit] = (counters[unit] ?? 0) + 1
  const item: VocabularyItem = {
    id: `v${unit}-${counters[unit]}`,
    unit,
    pos: posOf(kind),
    article: kind === 'der' || kind === 'die' || kind === 'das' ? (kind as Article) : undefined,
    de,
    plural: plural || undefined,
    ru,
    ky,
    example,
    exampleRu,
    ...(exampleKy ? { exampleKy } : {}),
    ...(pluralOnly ? { pluralOnly: true } : {}),
    related: [],
  }
  return item
})

