// Related words on the new curriculum units follow their curated semantic groups; legacy units keep their original neighbours.
export const VOCABULARY: VocabularyItem[] = base.map((v, i) => {
  const groups = curriculumRelatedGroups[v.unit]
  if (!groups) {
    return {
      ...v,
      related: [base[i - 1], base[i + 1], base[i + 2]]
        .filter((n): n is VocabularyItem => !!n && n.unit === v.unit)
        .map(n => n.id),
    }
  }
  const position = Number(v.id.slice(v.id.lastIndexOf('-') + 1))
  const group = groups.find(g => g.includes(position))
  const index = group?.indexOf(position) ?? -1
  return {
    ...v,
    related: group && index >= 0
      ? [group[index - 1], group[index + 1]].filter((n): n is number => n !== undefined).map(n => `v${v.unit}-${n}`)
      : [],
  }
})

export const vocabById = new Map(VOCABULARY.map(v => [v.id, v]))
export const vocabForUnit = (unit: number) => VOCABULARY.filter(v => v.unit === unit)
export const displayWord = (v: VocabularyItem) => (v.article ? `${v.article} ${v.de}` : v.de)

/** Case forms for masculine / feminine / neuter nouns; used in the rich vocabulary card. */
export function caseForms(v: VocabularyItem) {
  if (!v.article) return null
  if (v.pluralOnly) {
    const dativePlural = v.de.endsWith('n') || v.de.endsWith('s') ? v.de : `${v.de}n`
    return { nom: `die ${v.de}`, akk: `die ${v.de}`, dat: `den ${dativePlural}` }
  }
  const a = v.article
  const akk = a === 'der' ? 'den' : a
  const dat = a === 'die' ? 'der' : 'dem'
  return { nom: `${a} ${v.de}`, akk: `${akk} ${v.de}`, dat: `${dat} ${v.de}` }
}
